-- ─── 2. One SCHOOL sub-district per area ───
INSERT INTO essentials.districts (id, geo_id, district_id, label, district_type, state, mtfcc, representation_basis)
SELECT gen_random_uuid(), v.geo_id, v.geo_id, v.label, 'SCHOOL', 'CA', 'X0002', 'residency'
  FROM (VALUES
    ('0614400-ta-1', 'Fremont Unified School Board - Trustee Area 1'),
    ('0614400-ta-2', 'Fremont Unified School Board - Trustee Area 2'),
    ('0614400-ta-3', 'Fremont Unified School Board - Trustee Area 3'),
    ('0614400-ta-4', 'Fremont Unified School Board - Trustee Area 4'),
    ('0614400-ta-5', 'Fremont Unified School Board - Trustee Area 5')
  ) AS v(geo_id, label)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.districts d WHERE d.geo_id = v.geo_id);

-- ─── 3. Repoint each office to its own area (old value recorded in the header) ───
UPDATE essentials.offices o
   SET district_id = d.id
  FROM (VALUES
    ('dbd6207f-b5d1-469e-82ce-5e7ce4a6264a'::uuid, '0614400-ta-1'),
    ('5415b91d-a92e-484f-a086-c4bf77f6ae4a'::uuid, '0614400-ta-2'),
    ('7a095172-5e28-4101-9787-4022f0b33631'::uuid, '0614400-ta-3'),
    ('4144cce9-5341-46d1-ae49-726ae27bfaf8'::uuid, '0614400-ta-4'),
    ('95a508ab-74a3-41e3-ba84-8d4f4b8db58d'::uuid, '0614400-ta-5')
  ) AS v(office_id, geo_id)
  JOIN essentials.districts d ON d.geo_id = v.geo_id AND d.district_type = 'SCHOOL'
 WHERE o.id = v.office_id
   AND o.district_id = '7a459708-1634-4d3b-b35a-ed4ca46de41a'::uuid;

-- ─── 4. Post-verify ───
DO $$
DECLARE n int; bad text;
BEGIN
  -- 4a. five valid, non-empty polygonal geofences, one per area
  SELECT count(*) INTO n FROM essentials.geofence_boundaries
   WHERE geo_id LIKE '0614400-ta-_' AND mtfcc = 'X0002' AND state = '06'
     AND public.ST_IsValid(geometry) AND NOT public.ST_IsEmpty(geometry)
     AND public.GeometryType(geometry) = 'MULTIPOLYGON';
  IF n <> 5 THEN RAISE EXCEPTION 'CC_0519: expected 5 valid X0002 trustee-area geofences, found %', n; END IF;

  -- 4b. areas do not overlap, and their union covers the district's land as measured in the header
  SELECT count(*) INTO n FROM essentials.geofence_boundaries a JOIN essentials.geofence_boundaries b
      ON a.geo_id < b.geo_id AND a.mtfcc = 'X0002' AND b.mtfcc = 'X0002'
   WHERE a.geo_id LIKE '0614400-ta-_' AND b.geo_id LIKE '0614400-ta-_'
     AND public.ST_Area(public.ST_Intersection(a.geometry, b.geometry)::geography) > 1;
  IF n <> 0 THEN RAISE EXCEPTION 'CC_0519: % overlapping trustee-area pairs', n; END IF;
  PERFORM 1 FROM (
    SELECT public.ST_Area(public.ST_Intersection(u.g, f.geometry)::geography) / public.ST_Area(f.geometry::geography) AS r
      FROM (SELECT public.ST_Union(geometry) g FROM essentials.geofence_boundaries
             WHERE geo_id LIKE '0614400-ta-_' AND mtfcc = 'X0002') u,
           essentials.geofence_boundaries f
     WHERE f.geo_id = '0614400' AND f.mtfcc = 'G5420') x
   WHERE x.r BETWEEN 0.900 AND 0.903;
  IF NOT FOUND THEN RAISE EXCEPTION 'CC_0519: trustee-area union no longer covers 0.900-0.903 of the G5420 outline (measured 0.90128)'; END IF;

  -- 4c. each office sits on the area its OWN TITLE names, and is held by the trustee the district lists there.
  --     Asserts the discriminating fields (title number = geo_id suffix = roster name), not a count.
  SELECT string_agg(o.title || ' -> ' || coalesce(d.geo_id, 'NULL') || ' / ' || coalesce(p.full_name, 'NULL'), '; ') INTO bad
    FROM essentials.offices o
    LEFT JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
    LEFT JOIN essentials.politicians p ON p.id = och.politician_id
    JOIN (VALUES
      ('dbd6207f-b5d1-469e-82ce-5e7ce4a6264a'::uuid, '1', 'Sharon Coco'),
      ('5415b91d-a92e-484f-a086-c4bf77f6ae4a'::uuid, '2', 'Larry Sweeney'),
      ('7a095172-5e28-4101-9787-4022f0b33631'::uuid, '3', 'Dianne Jones'),
      ('4144cce9-5341-46d1-ae49-726ae27bfaf8'::uuid, '4', 'Rinu Nair'),
      ('95a508ab-74a3-41e3-ba84-8d4f4b8db58d'::uuid, '5', 'Vivek Prasad')
    ) AS v(id, n, holder) ON v.id = o.id
   WHERE d.geo_id IS DISTINCT FROM '0614400-ta-' || v.n
      OR o.title <> 'Board Member (Area ' || v.n || ')'
      OR p.full_name IS DISTINCT FROM v.holder
      OR d.district_type <> 'SCHOOL' OR d.mtfcc <> 'X0002';
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'CC_0519: office/area/holder mismatch: %', bad; END IF;

  -- 4d. nothing left on the whole-district row, and exactly one office per new area
  SELECT count(*) INTO n FROM essentials.offices WHERE district_id = '7a459708-1634-4d3b-b35a-ed4ca46de41a'::uuid;
  IF n <> 0 THEN RAISE EXCEPTION 'CC_0519: % offices still on the whole-district row', n; END IF;
  SELECT count(*) INTO n FROM (
    SELECT d.geo_id FROM essentials.districts d JOIN essentials.offices o ON o.district_id = d.id
     WHERE d.geo_id LIKE '0614400-ta-_' GROUP BY d.geo_id HAVING count(*) = 1) s;
  IF n <> 5 THEN RAISE EXCEPTION 'CC_0519: expected 5 areas with exactly one office each, found %', n; END IF;

  -- 4e. a point lookup returns exactly ONE trustee: Fremont City Hall (3300 Capitol Ave), the smoke point of
  --     migration 211. Whichever area it is, it must be one, through the same X0002 -> SCHOOL join the API uses.
  SELECT count(DISTINCT o.id) INTO n
    FROM essentials.geofence_boundaries gb
    JOIN essentials.districts d ON d.geo_id = gb.geo_id AND gb.mtfcc = 'X0002' AND d.district_type = 'SCHOOL'
    JOIN essentials.offices o ON o.district_id = d.id
   WHERE gb.geo_id LIKE '0614400-ta-_'
     AND public.ST_Covers(gb.geometry, public.ST_SetSRID(public.ST_MakePoint(-121.9886, 37.5483), 4326));
  IF n <> 1 THEN RAISE EXCEPTION 'CC_0519: City Hall point resolves to % FUSD trustees, expected 1', n; END IF;

  RAISE NOTICE 'CC_0519 OK: 5 trustee areas loaded, 5 offices repointed, City Hall -> 1 trustee';
END $$;

COMMIT;
